(() => {
  "use strict";
  const { makeChapter, flowDiagram, btreeFigure, callout, experiment } = globalThis.courseKit;
  const partTitle = "第8部 RDB";
  const total = 10;
  const dbSafety = callout("warning", "検証DB限定", "この章のSQLは自分のlesson_rdb検証DBだけで実行してください。CREATE・INSERT・UPDATE・DELETEを含む実験があります。本番・共有DBでは実行せず、既存の表名やデータを確認してから、終了後に作成した表だけを片付けます。");
  const chapter = (data, content) => makeChapter({ ...data, partTitle, total }, { ...content, lab: `${dbSafety}<p>使うのはローカルの検証用MySQLです。コードに <code>mysql -uroot</code> で始まる行がある場合は端末で実行し、接続後の <code>mysql&gt;</code> でSQLを入力します。</p>${content.lab}` });
  const diagram = (title, nodes, caption) => flowDiagram(title, nodes, caption);
  const mvccFigure = () => `<figure class="concept-figure">
    <p class="diagram-title" id="mvcc-comparison-title">同じ行を見る三つのTransaction</p>
    <p>各列が一つのTransactionです。上から時間順に読み、中央の行で、Aが更新を確定していない間にBとCがどう動くかを比べてください。</p>
    <table class="time-comparison" aria-labelledby="mvcc-comparison-title">
      <thead><tr><th scope="col">A<br>更新</th><th scope="col">B<br>Snapshot Read</th><th scope="col">C<br>FOR UPDATE</th></tr></thead>
      <tbody>
        <tr><td data-visual-role="input">100を読む</td><td data-visual-role="input">Snapshot<wbr>を作る</td><td>要求前</td></tr>
        <tr><td data-visual-role="wait">80に更新<br>未確定</td><td data-visual-role="process">Undoから<br>100を読む</td><td data-visual-role="wait">AのLockを待つ</td></tr>
        <tr><td data-visual-role="store">COMMIT<br>80を確定</td><td>—</td><td data-visual-role="store">80を読む</td></tr>
      </tbody>
    </table>
    <figcaption class="visual-caption">BはAの確定を待たずに旧バージョンの値100を読みます。CのFOR UPDATEはAがLockを解放するまで待ち、確定した値80を読みます。</figcaption>
  </figure>`;
  const dbSetup = `mysql -uroot -p -e "CREATE DATABASE IF NOT EXISTS lesson_rdb;"\nmysql -uroot -p lesson_rdb`;

  const partChapters = [
    chapter({ id: "relational-model", no: 1, shortTitle: "Relational Model", title: "Relational Model：表でデータを組み立てる", deck: "RDBは、データを表・行・列として整理し、SQLで組み合わせます。生徒名簿と成績表を例に、重複を減らす表の分け方まで進みます。" }, {
      reading: "約24分",
      goals: ["Table・Row・Columnの関係", "主キーで一行を区別する方法", "正規化で重複と更新漏れを減らす理由", "表を分けてもJOINで一つの答えを作れること"],
      why: `<p>紙に「田中さん、数学、90点」を一枚ずつ書けば始められます。しかし住所や科目名を何度も写すと、住所だけ変わったとき一部の行を直し忘れます。RDBはデータの形と関係を決め、同じ事実を何度も持たないようにする道具です。</p><p>Relational Modelがなければ、アプリごとに自由なデータ形式が増え、検索・更新・整合性のルールを共有しにくくなります。表という単純な形から始めることで、データの正しさをDBが検査できます。</p>${callout("important", "基本", "Tableは表、Rowは一件、Columnは項目です。SQLの`SELECT`は表の行と列から必要な答えを作ります。")}`,
      example: `<p>生徒表<code>students(id, name, class)</code>と成績表<code>scores(student_id, subject, point)</code>を作ります。生徒表の<code>id=7</code>が田中さんを表し、成績表の<code>student_id=7</code>がその生徒の数学の点数を指します。名前を成績表へ毎回コピーしないため、名前変更は一か所で済みます。</p><p>「田中さんの数学の点数」は二つの表を<code>student_id</code>でJOINして作ります。分けることは情報を捨てることではなく、同じ事実をつなぐ鍵を残すことです。</p>
    <h3>JOINで成績の行が何行返るか</h3>
    <p>生徒7に数学と英語の成績が1行ずつあるとします。生徒表には同じIDの行が1行でも、成績表を結合した結果には2行出ます。生徒7の名前はどちらの結果にも表示されますが、保存元は同じ生徒表の1行です。</p>
    <p>結果を数えるときは、何を1行として作ったかを先に決めましょう。この結合は「生徒一人で1行」ではなく「教科の成績一件で1行」です。人数を知りたい場合は、生徒IDの重複をどう扱うかが変わります。</p>`,
      internal: `${diagram("表と関係", [["students", "id=7 / 田中"], ["student_id", "同じ番号"], ["scores", "数学 / 90"], ["JOIN", "生徒＋点数"]], "表を分け、共通の番号で結び付けることで、重複を減らしながら必要な答えを作れます。")}<h3>Table・Row・Column</h3><p>Tableは同じ種類の事実を並べる入れ物です。Rowは一件のデータ、Columnは全行に共通する項目です。<code>students</code>の一行は一人の生徒、<code>name</code>列は名前だけを持つ、というように一行の意味を決めます。</p><h3>正規化</h3><p>正規化は、更新・追加・削除で矛盾が起きにくいように表を分ける考え方です。生徒名と住所を成績の全行へコピーする代わりに、生徒表へ一度だけ置きます。科目表を別にすれば、「数学」という文字の表記揺れも減ります。</p><h3>JOINの因果</h3><p>JOINは二つの表を共通の値で照合します。DBは片方の行を読み、条件に合うもう片方の行を探して結果の一行へまとめます。どの列が同じ事実を指すかを設計していないと、間違った組み合わせや大量の行が生まれます。</p>`,
      web: `<p>Web APIの<code>GET /students/7/scores</code>は、ControllerがSQLを実行し、studentsとscoresをJOINしてJSONへ変換する例です。DBの表設計がよいと、名前変更や点数追加の処理を一つの事実へ適用できます。</p><p>正規化は常に表を細かくすればよいという意味ではありません。読み取り速度のために重複列を持つ非正規化もありますが、更新元と同期方法を決めてから選びます。第6部のB+Treeは、こうした表から行を速く探す仕組みです。</p>`,
      lab: `${experiment("MySQL 検証DB（macOS / Linux）", `${dbSetup}\nCREATE TABLE students (id INT PRIMARY KEY, name VARCHAR(40), class_name VARCHAR(20));\nCREATE TABLE scores (student_id INT, subject VARCHAR(20), point INT,\n  PRIMARY KEY (student_id, subject));\nINSERT INTO students VALUES (7,'田中','1-A');\nINSERT INTO scores VALUES (7,'数学',90);\nSELECT s.name, c.subject, c.point FROM students s JOIN scores c ON s.id=c.student_id;`, "安全なlesson_rdbデータベースで、表を分けてJOINする結果を確認します。", "同じstudent_id=7が関係をつなぎ、名前がscoresへ重複保存されていない点に注目します。", "正規化した表でもJOINで一つの画面用データを作れると分かります。")}`,
      misunderstandings: [["Tableを分けると、アプリから一緒に読めません。", "共通の鍵でJOINすれば、分けた表から必要な結果を作れます。"], ["正規化とは、すべての表をできるだけ小さくすることです。", "更新時の矛盾を減らすために事実の単位を分ける考え方で、読み取り性能との調整も必要です。"]],
      questions: [["Rowは何を表しますか。","表の中の一件のデータです。","Rowは列名を並べる見出しです。","Rowは表全体をまとめる入れ物です。","「表の中の一件のデータです。」が正しいのは、Rowは一件分の事実を表すため。誤答1の「Rowは列名を並べる見出しです。」は列名だけを示すものとしている。誤答2の「Rowは表全体をまとめる入れ物です。」は表全体と一行を取り違えている。"],["Columnは何を表しますか。","全行に共通する項目や属性です。","Columnは表の一件全体を表します。","Columnは表どうしを結ぶ鍵だけを表します。","「全行に共通する項目や属性です。」が正しいのは、Columnは全Rowに共通する項目や属性を表すため。誤答1の「Columnは表の一件全体を表します。」は一つのRowと同じものとしている。誤答2の「Columnは表どうしを結ぶ鍵だけを表します。」は関係を結ぶKeyだけに狭めている。"],["正規化の主な目的は何ですか。","同じ事実の重複を減らし、更新漏れや矛盾を減らすことです。","正規化は表の数を増やす作業だけです。","正規化は同じ値を多くのRowへコピーする方法です。","「同じ事実の重複を減らし、更新漏れや矛盾を減らすことです。」が正しいのは、同じ事実を一か所に置き、更新時の矛盾を減らすため。誤答1の「正規化は表の数を増やす作業だけです。」は表を分ける数だけが目的だとしている。誤答2の「正規化は同じ値を多くのRowへコピーする方法です。」は重複を増やす方法としている。"],["studentsとscoresを結ぶ値は何ですか。","students.idとscores.student_idです。","studentsとscoresはsubject名だけで結びます。","studentsとscoresは行番号だけで結びます。","「students．idとscores．student_idです。」が正しいのは、studentsのidとscoresのstudent_idが同じ生徒を指すため。誤答1の「studentsとscoresはsubject名だけで結びます。」は科目名だけでは生徒を一意に決められないため。誤答2の「studentsとscoresは行番号だけで結びます。」はDBで管理する関係Keyを使っていないため。"],["JOINは何をしますか。","共通の値を条件に複数表の行を組み合わせます。","JOINは表を削除して一つにします。","JOINは条件を見ず全Rowを必ず一対一にします。","「共通の値を条件に複数表の行を組み合わせます。」が正しいのは、共通値を条件に複数表のRowを結果へ組み合わせるため。誤答1の「JOINは表を削除して一つにします。」は結合を削除操作としている。誤答2の「JOINは条件を見ず全Rowを必ず一対一にします。」は照合条件を無視している。"],["非正規化を選ぶときに必要なことは何ですか。","重複データの更新元と同期方法を決めることです。","非正規化なら重複値の更新元を決めなくてよいです。","非正規化は必ず全ての表を一つに戻す方法です。","「重複データの更新元と同期方法を決めることです。」が正しいのは、重複列をどこで更新しどう同期するかを決めるため。誤答1の「非正規化なら重複値の更新元を決めなくてよいです。」は更新元の管理を不要としている。誤答2の「非正規化は必ず全ての表を一つに戻す方法です。」は表を一つにすることだけを意味している。"]],
      checks: ["Table・Row・Column", "表を分ける理由", "正規化と更新漏れ", "JOINのつなぎ方"], search: "RDB relational model table row column normalization normalize JOIN students scores"
    }),

    chapter({ id: "page-disk-io", no: 2, shortTitle: "PageとDisk I/O", title: "PageとDisk I/O：表を小さな箱で保存", deck: "DBは表をそのまま一枚の紙としてDiskへ置きません。固定サイズのPageへ分け、必要なPageを読み書きします。第2部のPage Cacheとの違いも整理します。" }, {
      reading: "約24分",
      goals: ["PageとRecordの関係", "Disk I/Oが遅くなりやすい理由", "InnoDBのデータファイルとPage", "DBのBuffer PoolとOSのPage Cacheの役割差"],
      why: `<p>磁気DiskやSSDからデータを読むには、CPUの計算より長い時間がかかることがあります。DBが毎回表全体を一行ずつ装置へ頼むと、少しの検索でも待ち時間が増えます。Pageというまとまりを使うのは、近くのデータをまとめて読み、I/O回数を減らすためです。</p><p>Pageがなければ、DBはメモリとDiskの間でどの範囲を読み、どの範囲を変更したか管理しにくくなります。DBはPage単位でCache、ロック、ログ、書き戻しを考えます。</p>`,
      example: `<p>10万行の表を、仮に100行ずつ入るPageへ分けると1000 Pageです。<code>id=7</code>を探すとき、Indexがあれば一つか数個のPageへ移動できます。Indexがなければ、最初のPageから順に多くのPageを読む全表走査になる可能性があります。</p><p>Pageを読んだデータはメモリへ載ります。二回目の検索がDiskではなくメモリから返ることがあるのは、InnoDBのBuffer PoolがPageを保持しているためです。</p>
    <h3>欲しい一行の周りも一緒に届く</h3>
    <p>行7と行8が同じデータPageにある例で、まず行7を読んでPageがメモリに載るとします。そのPageが残っている間は、行8を別の問い合わせで読んでも同じPageを使えます。行9が次のPageにあるなら、そちらがまだなければ追加の読み出しが必要です。</p>
    <p>検索の費用を考えるときは、結果の行数だけでなく、行がいくつのPageに散らばっているかも見ます。同じ10行を返す検索でも、1つのPageにまとまる場合と10個のPageに分かれる場合では、読み出しの回数が変わり得ます。</p>`,
      internal: `${diagram("InnoDBのPage読み込み", [["SQL", "WHERE id=7"], ["Index", "行の場所を探す"], ["Page", "行を含む箱"], ["Buffer Pool", "メモリ上の複製"], ["Disk", "永続データ"]], "DBはPageをBuffer Poolへ読み、必要なら変更したPageを後でDiskへ書き戻します。")}<h3>PageとRecord</h3><p>Recordは一行の保存単位、Pageは複数Recordや管理情報を含む一定サイズの領域です。InnoDBではデータやIndexをPageに分けて管理します。実際のサイズや内部形式はバージョン・設定で変わりますが、「I/Oの基本単位がまとまり」という考え方が重要です。</p><h3>Disk I/Oの待ち</h3><p>Pageがメモリにないと、DBはストレージから読み込む必要があります。CPUは読み込み完了まで別の仕事を進められる場合がありますが、そのSQLの答えは待ちます。ランダムに離れたPageを多数読むと、順番に近いPageを読むより負担が増えます。</p><h3>DB Buffer PoolとOS Page Cache</h3><p>第2部のOS Page Cacheは、ファイルのバイト列をOSがメモリへ保つ仕組みです。InnoDBのBuffer Poolは、DBがPageを理解し、Dirty Page、Index、置き換え、先読みなどを管理する領域です。Storageや設定によってはOS Cacheも関係しますが、同じものではありません。</p>`,
      web: `<p>SQLが遅いとき「CPUが遅い」と決めず、読み込んだPage数、Disk I/O、Buffer Pool hit率を確認します。アプリが小さな行一件を求めても、Indexがなければ大量Pageを読むため遅くなります。</p><p>Pageのサイズを直接意識するより、行の大きさ、Indexの有無、アクセスが連続かランダムかを設計へ反映します。第7章では、Buffer PoolのためSELECTが毎回Diskへ行くわけではない理由を詳しく扱います。</p>`,
      lab: `${experiment("MySQL 検証DB（macOS / Linux）", `${dbSetup}\nCREATE TABLE page_demo (id INT PRIMARY KEY, note CHAR(200));\nINSERT INTO page_demo SELECT seq, RPAD('x',200,'x') FROM (SELECT 1 seq UNION ALL SELECT 2 UNION ALL SELECT 3) t;\nSHOW TABLE STATUS LIKE 'page_demo'\\G;\nSHOW VARIABLES LIKE 'innodb_page_size';`, "検証表の概算サイズとInnoDBのPageサイズを確認します。", "Data_length、Index_length、innodb_page_sizeの値に注目します。", "表はPage単位で管理され、行サイズが増えると必要な保存領域も増えると分かります。")}${callout("note", "入力の拡張", "大量行を試す場合もlesson_rdb内だけで行い、不要になった表をDROPする前に対象名を確認してください。")}`,
      misunderstandings: [["DBのPageとOSのPage Cacheは同じものです。", "OSはファイルのバイト列をCacheし、InnoDB Buffer PoolはDBのPageを理解して管理します。層と責任が異なります。"], ["一行だけ読むSQLは必ずDiskから一行だけ読みます。", "必要なPage全体を読むため、Cache状況やIndexによってはPage単位のI/Oになります。"]],
      questions: [["Pageを使う理由は何ですか。","近いデータをまとめて読み書きし、I/Oと管理の単位をそろえるためです。","PageはSQLのWHERE条件そのものです。","Pageは一行ごとに必ず別のDisk I/Oを発生させます。","「近いデータをまとめて読み書きし、I/Oと管理の単位をそろえるためです。」が正しいのは、近いRecordをまとめ、I/Oと管理の単位をそろえるため。誤答1の「PageはSQLのWHERE条件そのものです。」は保存単位を検索条件と同一視している。誤答2の「Pageは一行ごとに必ず別のDisk I/Oを発生させます。」はまとまりで読む利点を逆にしている。"],["Indexがない検索で起きることは何ですか。","多くのPageを順に読む全表走査になる可能性があります。","Indexがなくても必ず一つのPageだけを読みます。","Indexがない検索は常に構文エラーになります。","「多くのPageを順に読む全表走査になる可能性があります。」が正しいのは、多くのPageを順に確認する全表走査になり得るため。誤答1の「Indexがなくても必ず一つのPageだけを読みます。」は全表走査の可能性を否定している。誤答2の「Indexがない検索は常に構文エラーになります。」は検索の実行可否と速度を混同している。"],["Buffer Poolは何を保持しますか。","InnoDBのPageをメモリ上へ保持します。","Buffer PoolはSQL文字列だけを保持します。","Buffer Poolは主Keyの番号だけを保持します。","「InnoDBのPageをメモリ上へ保持します。」が正しいのは、InnoDBのPageをメモリに保持して再利用するため。誤答1の「Buffer PoolはSQL文字列だけを保持します。」はDBのPageではなくSQL文だけを保存するとしている。誤答2の「Buffer Poolは主Keyの番号だけを保持します。」はPageの内容をKey番号だけに狭めている。"],["第2部のPage Cacheとの違いは何ですか。","Page CacheはOSのファイルCache、Buffer PoolはInnoDBがDBのPageとして管理するCacheです。","OS Page CacheとBuffer Poolは同じ領域の別名です。","OS Page CacheがDBのIndexやDirty状態まで管理します。","「Page CacheはOSのファイルCache、Buffer PoolはInnoDBがDBのPageとして管理するCacheです。」が正しいのは、OSはファイルByte列、InnoDBは内容を理解したDB Pageを管理するため。誤答1の「OS Page CacheとBuffer Poolは同じ領域の別名です。」は二つを同じCacheとしている。誤答2の「OS Page CacheがDBのIndexやDirty状態まで管理します。」はOS側にDB固有の管理まで任せている。"],["ランダムI/Oが負担になりやすい理由は何ですか。","離れたPageを多く読み、連続して読むより読み込みの待ちが増えやすいからです。","離れたPageほど必ず一度にまとめて読めます。","ランダムI/OはCPUの計算量だけを増やします。","「離れたPageを多く読み、連続して読むより読み込みの待ちが増えやすいからです。」が正しいのは、離れたPageを多く読むため、連続読込より待ちが増えやすいから。誤答1の「離れたPageほど必ず一度にまとめて読めます。」はランダム読込の負担を逆にしている。誤答2の「ランダムI/OはCPUの計算量だけを増やします。」はDiskアクセスではなくCPUだけの問題としている。"]],
      checks: ["PageとRecord", "Disk I/Oの待ち", "InnoDBの保存単位", "Buffer PoolとOS Page Cacheの差"], search: "InnoDB Page Disk I/O data page record Buffer Pool OS Page Cache innodb_page_size Data_length"
    }),

    chapter({ id: "primary-foreign-key", no: 3, shortTitle: "Primary KeyとForeign Key", title: "Primary KeyとForeign Key：行を一意に結ぶ", deck: "主キーは行を一つに決め、外部キーは別表の主キーを指します。番号の重複や存在しない参照をDBに止めてもらう仕組みです。" }, {
      reading: "約20分",
      goals: ["Primary Keyの一意性とNULL禁止", "Foreign Keyが表の関係を表す方法", "参照整合性と更新・削除", "InnoDBで制約を検証する流れ"],
      why: `<p>生徒を名前だけで探すと、同姓同名を区別できません。Primary Keyがなければ、「この一行」を安全に更新・削除する条件を作りにくくなります。外部キーがなければ、存在しない生徒番号の成績が保存され、後から誰の点数か分からなくなります。</p><p>制約はアプリの注意書きではなく、DBが受け入れてよいデータの条件です。複数のアプリやバッチが同じDBへ書く場合にも、参照整合性を守れます。</p>`,
      example: `<p><code>students.id=7</code>をPrimary Keyにし、<code>scores.student_id</code>をForeign Keyとしてstudents.idへ参照させます。<code>student_id=999</code>を追加しようとすると、999の生徒が存在しないため失敗します。</p><p>親の生徒を削除するとき、子の成績を残すのか、同時に削除するのかを決めます。<code>ON DELETE CASCADE</code>は便利ですが、親一行の削除で多くの子行が消えるため、意味を確認して使います。</p>
    <h3>誰の成績かと、何の成績かを区別する</h3>
    <p><code>scores.student_id</code>が生徒表の<code>id</code>を参照すれば、存在する生徒の成績だけを登録できます。それだけなら同じ生徒の数学を2行登録することもできます。生徒ごとに各教科の成績を一つにするなら、生徒IDと教科の組み合わせの一意性も決めます。</p>
    <p>外部キーを設計するときは「参照先が存在するか」を、主キーやUNIQUE制約では「同じものを何件まで持てるか」を考えます。二つの約束を分けると、表が何を表すかが明確になります。</p>`,
      internal: `${diagram("参照整合性", [["students", "PK id=7"], ["Foreign Key", "student_id=7"], ["scores", "子の行"], ["制約検査", "親の存在を確認"], ["COMMIT", "確定"]], "Foreign Keyは、子の値が親表の実在するKeyを指すことを確認します。")}<h3>Primary Key</h3><p>Primary Keyは表の各行を一意に識別する列または列の組です。重複できず、通常NULLも許されません。InnoDBでは主キーがClustered Indexの並びとデータ保存の中心になります。</p><h3>Foreign Key</h3><p>Foreign Keyは、別表のPrimary Keyなどを参照する列です。子表の値が親表に存在するかを確認し、孤児行を防ぎます。これは列名が同じというだけではなく、DBへ明示的に制約を定義して初めて検査されます。</p><h3>更新と削除の順番</h3><p>親Keyを変更・削除すると、子行が参照できなくなる可能性があります。RESTRICTなら子がある間は拒否、CASCADEなら子も連動、SET NULLなら子の参照をNULLにする、というようにルールを選びます。業務の意味とNULL許可を合わせます。</p>`,
      web: `<p>APIのURLに<code>/students/7</code>とあっても、数字を受け取っただけで正しいとは限りません。SQLのWHERE条件とForeign Keyが別々に検証し、存在しない親や権限外の行を返さないようにします。</p><p>分散処理や外部システム連携では、Foreign Keyを使わずアプリで整合性を保つ場合もあります。そのときは再試行や削除順を含め、制約をどこが担当するか明確にします。</p>`,
      lab: `${experiment("MySQL 検証DB（macOS / Linux）", `${dbSetup}\nCREATE TABLE parent (id INT PRIMARY KEY);\nCREATE TABLE child (id INT PRIMARY KEY, parent_id INT,\n  CONSTRAINT fk_child_parent FOREIGN KEY (parent_id) REFERENCES parent(id));\nINSERT INTO parent VALUES (1);\nINSERT INTO child VALUES (10,1);\nINSERT INTO child VALUES (11,999);`, "正しい親参照は通り、存在しない親へのINSERTは止まることを確認します。", "最後のINSERTのERROR、SHOW CREATE TABLEの制約名に注目します。", "Foreign Keyがアプリの都合ではなくInnoDBの制約として働くと分かります。")}${experiment("MySQL 検証DB（macOS / Linux）", `SHOW CREATE TABLE child\\G\nSELECT CONSTRAINT_NAME, REFERENCED_TABLE_NAME\nFROM information_schema.KEY_COLUMN_USAGE\nWHERE TABLE_SCHEMA='lesson_rdb' AND TABLE_NAME='child';`, "定義したForeign KeyをDBのメタデータで確認します。", "CONSTRAINT_NAMEと参照先の表・列に注目します。", "関係がSQL定義として保存され、後から調査できると分かります。")}`,
      misunderstandings: [["Foreign Keyは、同じ名前の列なら自動で効きます。", "CREATE TABLEなどで制約として定義した場合に、InnoDBが参照整合性を検査します。"], ["Primary Keyは検索を速くするだけのIndexです。", "検索にも使われますが、各行を一意に識別し、InnoDBのデータ配置の中心になる意味があります。"]],
      questions: [["Primary Keyの条件は何ですか。","各行を一意に識別でき、重複せず通常NULLを許さないことです。","Primary Keyは同じ値を複数Rowで持てます。","Primary Keyは必ず文字列でなければなりません。","「各行を一意に識別でき、重複せず通常NULLを許さないことです。」が正しいのは、各Rowを一意に識別し、重複せず通常NULLも許さないため。誤答1の「Primary Keyは同じ値を複数Rowで持てます。」は一意性を否定している。誤答2の「Primary Keyは必ず文字列でなければなりません。」は型を不要に限定している。"],["Foreign Keyの目的は何ですか。","子表の値が親表の実在するKeyを指すことを保証することです。","Foreign Keyは子Rowを暗号化します。","Foreign Keyは列名が同じなら自動で働きます。","「子表の値が親表の実在するKeyを指すことを保証することです。」が正しいのは、子表の値が親表に存在するかをDBに確認させるため。誤答1の「Foreign Keyは子Rowを暗号化します。」は参照関係を暗号化と取り違えている。誤答2の「Foreign Keyは列名が同じなら自動で働きます。」は明示的な関係定義を不要としている。"],["存在しないparent_idをINSERTするとどうなりますか。","Foreign Key制約により失敗します。","存在しないparent_idでも警告だけで保存されます。","DBがparent_idを0へ変換して保存します。","「Foreign Key制約により失敗します。」が正しいのは、親に対応するKeyがないためINSERTを受け付けないため。誤答1の「存在しないparent_idでも警告だけで保存されます。」は参照検査を警告だけの処理としている。誤答2の「DBがparent_idを0へ変換して保存します。」は値を自動変換する処理としている。"],["ON DELETE CASCADEの注意点は何ですか。","親一行の削除で参照する子行も削除されることです。","親Rowを消しても子Rowは必ず残ります。","CASCADEは親Rowの削除を禁止します。","「親一行の削除で参照する子行も削除されることです。」が正しいのは、親Rowの削除に合わせて参照する子Rowも削除するため。誤答1の「親Rowを消しても子Rowは必ず残ります。」は連動削除を否定している。誤答2の「CASCADEは親Rowの削除を禁止します。」はCASCADEを拒否指定としている。"],["列名が同じだけで参照整合性が働かないのはなぜですか。","DBへForeign Key制約を定義していないからです。","Foreign Keyは子Rowを暗号化します。","Foreign Keyは列名が同じなら自動で働きます。","「DBへForeign Key制約を定義していないからです。」が正しいのは、子表の値が親表に存在するかをDBに確認させるため。誤答1の「Foreign Keyは子Rowを暗号化します。」は参照関係を暗号化と取り違えている。誤答2の「Foreign Keyは列名が同じなら自動で働きます。」は明示的な関係定義を不要としている。"]],
      checks: ["Primary Keyの一意性", "Foreign Keyの参照", "参照整合性", "削除・更新ルール"], search: "Primary Key PK Foreign Key FK referential integrity InnoDB CASCADE RESTRICT SET NULL SHOW CREATE TABLE"
    }),

    chapter({ id: "bplus-tree-index", no: 4, shortTitle: "IndexとB+Tree", title: "IndexとB+Tree：探す道を短くする", deck: "Indexは本の索引に似ています。InnoDBのB+TreeがPageをどうつなぎ、10万行からid=7へ近づくかを、全表走査と比べます。" }, {
      reading: "約24分",
      goals: ["Indexが全表走査を減らす理由", "B+TreeのRoot・Internal・Leaf", "Range検索とLeafの横連結", "Index追加による書き込みコスト"],
      why: `<p>索引のない1万ページの本から「7ページにある言葉」を探すには、最初からめくる必要があります。DBの全表走査も同じで、条件に合う行を見つけるまで多くのPageを読みます。Indexがなければ、少数行を求めるSQLでもI/Oが増えます。</p><p>Indexは検索を速くする一方、INSERT・UPDATE・DELETEのたびに索引も更新し、Disk容量とBuffer Poolを使います。存在しない場合の遅さと、作りすぎた場合の負担を比べる必要があります。</p>`,
      example: `<p><code>CREATE INDEX idx_users_email ON users(email)</code>を作ると、emailの値を順序づけた道ができます。<code>WHERE email='a@example.com'</code>ならRootから分岐を選び、数回のPage読み込みでLeafへ着きます。Leafには値と主キーなどの行を見つける情報があります。</p><p><code>WHERE id BETWEEN 100 AND 120</code>のような範囲条件では、最初のLeafを見つけた後、隣のLeafへ順に進めます。B+TreeのLeafが横につながる設計は、範囲を読むのに向いています。</p>
    <h3>一件を探すときと、範囲を読むとき</h3>
    <p>利用者ID 77だけを検索するなら、Rootから境界キーを比較し、該当するLeafで77を探します。70〜85なら70が入る範囲のLeafから始め、隣のLeafへ進んで85まで読みます。最初の場所を決める手順は共通で、その後に読む葉の数が違います。</p>
    <p>対象の範囲が広いと、Indexから候補を見つけても多くの行を読むことになります。検索条件にIndexが使えるかと、実際に少ない読み出しで済むかを分けて考えましょう。</p>`,
      internal: `${btreeFigure("InnoDBのB+Treeを上から下へたどる", "枠が太いページは77を探す経路です。70〜85の範囲検索ではLeaf BからLeaf Cへ進みます。")}${flowDiagram("Index検索の続き", [["Leafで候補発見", "emailと主キー"], ["Clustered Index", "主キーで本体へ"], ["Table Row", "必要な列を読む"]], "Secondary Indexでは、Leafで得た主キーから本体のB+Treeへもう一度進む場合があります。", {animate:true})}<h3>高さを小さく保つ</h3><p>B+Treeは一つのPageへ複数のキーと子Pageへの案内を入れます。枝分かれを多くすると、百万件あってもRootからLeafまでを数段に抑えやすくなります。</p><h3>LeafとRange</h3><p>Leafは検索値と行を見つける情報を持ち、隣のLeafへのリンクで範囲をたどります。範囲が広すぎる場合は多くのLeafと本体Pageを読むため、全表走査との差が小さくなることもあります。</p><h3>第6部との違い</h3><p>データ構造としては木の高さと比較回数を考えます。RDBではさらに、Page I/O、主キーへのLookup、更新Logの費用が加わります。</p>`,
      web: `<p>APIで<code>WHERE user_id=?</code>が頻繁ならIndex候補です。ただし取得件数が表の大半なら、Indexから一行ずつ本体へ行くより全表走査が速いこともあります。Optimizerは統計を使って選びますが、実データをEXPLAINで確認します。</p><p>Indexの列順、更新頻度、Selectivity（条件で何割まで絞れるか）をまとめて考えます。Indexを増やせば必ず速いわけではありません。</p>`,
      lab: `${experiment("MySQL 検証DB（macOS / Linux）", `${dbSetup}\nCREATE TABLE idx_demo (id INT PRIMARY KEY, email VARCHAR(100), score INT);\nINSERT INTO idx_demo VALUES (1,'a@example.com',80),(2,'b@example.com',90),(3,'c@example.com',70);\nEXPLAIN SELECT * FROM idx_demo WHERE email='b@example.com';\nCREATE INDEX idx_demo_email ON idx_demo(email);\nEXPLAIN SELECT * FROM idx_demo WHERE email='b@example.com';`, "Index作成前後の実行計画を比べます。", "type、possible_keys、key、rowsの変化に注目します。", "同じWHEREでも、Indexの有無でOptimizerが選ぶ読み方が変わると分かります。")}${callout("note", "データ量", "3行だけでは全表走査が合理的なこともあります。大きな表で差が出る仕組みを理解し、EXPLAINの値を実データで判断してください。")}`,
      misunderstandings: [["Indexがあれば、どんな検索も一行だけ読めます。", "条件の範囲、選択性、必要な列、表の大きさによって多くのPageを読む場合があります。"], ["Indexは検索専用で、書き込みには影響しません。", "行を追加・変更・削除するたびにIndexも更新するため、書き込みと容量のコストがあります。"]],
      questions: [["Indexの主な目的は何ですか。","条件に合う行の場所へ短い道で到達し、全表走査を減らすことです。","Indexは読み取りだけを保存し書き込みを行いません。","Indexは表の全Rowを常にメモリへ置きます。","「条件に合う行の場所へ短い道で到達し、全表走査を減らすことです。」が正しいのは、Keyによる検索で読む範囲を絞りやすくするため。誤答1の「Indexは読み取りだけを保存し書き込みを行いません。」はIndex更新の負荷を否定している。誤答2の「Indexは表の全Rowを常にメモリへ置きます。」はIndexと全件Cacheを同一視している。"],["B+Treeで最初に見るPageは何ですか。","Root Pageです。","最初に全Leaf Pageを読みます。","最初にRowデータを順番に全件読みます。","「Root Pageです。」が正しいのは、Root Pageから条件に合う枝を選ぶため。誤答1の「最初に全Leaf Pageを読みます。」は木の上から絞る順序を逆にしている。誤答2の「最初にRowデータを順番に全件読みます。」はIndexなしの走査を最初の処理としている。"],["Leaf Pageが横につながる利点は何ですか。","見つけた開始点から範囲を順に読みやすいことです。","Leafは互いに独立して次をたどれません。","横リンクがあると範囲検索のたびにRootへ戻ります。","「見つけた開始点から範囲を順に読みやすいことです。」が正しいのは、開始位置から隣のLeafへ進み、範囲Keyを連続して読めるため。誤答1の「Leafは互いに独立して次をたどれません。」はLeaf間の移動を否定している。誤答2の「横リンクがあると範囲検索のたびにRootへ戻ります。」は範囲検索の進み方を逆にしている。"],["Indexが大きすぎる範囲で効きにくい理由は何ですか。","多くのLeafや本体Pageを読むことになり、全表走査との差が小さくなるからです。","検索範囲が広いほどIndexは全Rowを削除します。","Leafが増えるほど必ず一つのPageだけで答えられます。","「多くのLeafや本体Pageを読むことになり、全表走査との差が小さくなるからです。」が正しいのは、多くのLeafや本体Pageを読むため全表走査との差が小さくなるから。誤答1の「検索範囲が広いほどIndexは全Rowを削除します。」はIndexを使うとデータが消えるとしている。誤答2の「Leafが増えるほど必ず一つのPageだけで答えられます。」は読むPageが減ると逆にしている。"],["Indexを追加するとINSERTが重くなる理由は何ですか。","新しい行の値を各Indexへ追加し、必要ならPage分割も行うからです。","Index追加後はINSERTが実行できません。","Indexがあっても追加した値をIndexへ反映しません。","「新しい行の値を各Indexへ追加し、必要ならPage分割も行うからです。」が正しいのは、新しい値を各Indexへ追加し必要ならPage分割も行うため。誤答1の「Index追加後はINSERTが実行できません。」は実行不能という極端な結果にしている。誤答2の「Indexがあっても追加した値をIndexへ反映しません。」はIndex更新を省略している。"]],
      checks: ["全表走査とIndex", "B+Treeの三層", "Leafの範囲走査", "Indexの読み取り・書き込みコスト"], search: "Index B+Tree B-tree Root Internal Leaf Page range scan EXPLAIN selectivity InnoDB"
    }),

    chapter({ id: "clustered-secondary-composite", no: 5, shortTitle: "ClusteredとComposite Index", title: "Clustered・Secondary・Composite Index：列順の設計", deck: "InnoDBの主キーの木と、追加したSecondary Indexの木は役割が違います。INDEX(a,b)がWHERE bだけで効きにくい理由を、木の並びで確認します。" }, {
      reading: "約24分",
      goals: ["Clustered Indexと主キーのデータ配置", "Secondary Indexから主キーへ戻る流れ", "Composite Indexの左端列ルール", "INDEX(a,b)がWHERE bだけで効きにくい理由"],
      why: `<p>同じ「Index」という名前でも、主キーの木と追加Indexの木では、Leafに置かれる情報が違います。ここを混同すると、Indexを一度読むだけだと思い込み、実際には本体Pageへ追加で移動する処理を見落とします。</p><p>複数条件の検索では列の順番も道の形を決めます。INDEX(a,b)が存在しても、bだけを指定した検索でaの順序を飛び越えて効率よく絞れるとは限りません。</p>`,
      example: `<p>InnoDBの表に主キー<code>id</code>があると、Clustered IndexのLeafが行データを持つ中心になります。<code>INDEX(a,b)</code>というSecondary IndexのLeafには、a・bの値と主キーidが並びます。</p><p>並びが<code>(a=1,b=10),(a=1,b=20),(a=2,b=5)</code>なら、aを先にまとめてからbを並べています。b=5だけを探すと、a=1の範囲、a=2の範囲…を広く調べる必要があり、aのない検索では効きにくいのです。</p>
    <h3>複合Indexを辞書の並び順で読む</h3>
    <p><code>INDEX(a, b)</code>は、まずaで並べ、同じaの中でbを並べた形です。<code>a = 1 AND b BETWEEN 10 AND 20</code>なら、aが1の区間の中でbの範囲を絞れます。<code>b = 10</code>だけなら、aの異なる区間にも値10が現れ得ます。</p>
    <p>結果に必要な列も見ましょう。Index内の値だけで結果を作れる場合と、候補の主キーから表の本体へ行を取りに行く場合では、同じIndexを使っても追加の仕事が変わります。</p>`,
      internal: `${diagram("ClusteredとSecondary", [["Secondary Leaf", "a,b → id"], ["主キーid", "戻り先"], ["Clustered Leaf", "id＋行全体"], ["結果", "必要列を返す"]], "Secondary Indexで候補の主キーを得た後、本体行が必要ならClustered Indexへ戻るLookupが起きます。")}<h3>Clustered Index</h3><p>InnoDBでは、主キーのB+TreeのLeafに行データが置かれます。主キーで探すと、Leafへ着いた時点で本体の列を読めます。主キーが長いとSecondary Indexの各Leafへ保存する主キーも大きくなり、Index全体が膨らむことがあります。</p><h3>Secondary Index</h3><p>追加IndexのLeafは、条件列と主キーを持ちます。SELECTがIndexに含まれる列だけなら、主キーへ戻らず答えられるCovering Indexになることがあります。含まれない列が必要なら、候補の主キーごとにClustered Indexへ戻ります。</p><h3>左端列ルール</h3><p>INDEX(a,b)はまずaで大きく分け、その中でbを並べた木です。<code>WHERE a=3 AND b=8</code>や<code>WHERE a=3</code>は左端aから道を選べます。しかし<code>WHERE b=8</code>だけでは最初に選ぶaがなく、木全体の多くを調べる必要があります。OptimizerがIndex Skip Scanなど別の方法を選ぶ場合はありますが、基本設計として左端列を意識します。</p>`,
      web: `<p>ログ一覧を<code>WHERE tenant_id=? AND created_at&gt;?</code>で取るなら、<code>INDEX(tenant_id, created_at)</code>はテナントで絞ってから時刻範囲を読む道になります。逆にcreated_atだけの全テナント検索には別のIndexが必要なことがあります。</p><p>SELECTで必要な列をIndexへ含めればLookupを減らせますが、Indexのサイズと更新費用が増えます。クエリの実際の条件、返す列、データ分布をEXPLAINで確認します。</p>`,
      lab: `${experiment("MySQL 検証DB（macOS / Linux）", `${dbSetup}\nCREATE TABLE composite_demo (id INT PRIMARY KEY, a INT, b INT, note VARCHAR(30));\nINSERT INTO composite_demo VALUES (1,1,10,'x'),(2,1,20,'y'),(3,2,10,'z'),(4,2,30,'w');\nCREATE INDEX idx_ab ON composite_demo(a,b);\nEXPLAIN SELECT * FROM composite_demo WHERE a=2 AND b=10;\nEXPLAIN SELECT * FROM composite_demo WHERE b=10;\nEXPLAIN SELECT a,b FROM composite_demo WHERE a=2 AND b=10;`, "同じComposite Indexで、aあり・bだけ・Index内の列だけを比べます。", "key、key_len、rows、ExtraのUsing indexに注目します。", "左端aを指定できる検索ほど道を絞りやすく、SELECT列がIndex内だけならLookupを省けると分かります。")}${callout("important", "指定疑問への答え", "INDEX(a,b)がWHERE bだけで効きにくいのは、B+Treeがa→bの順に並び、aを決めないとbの連続した範囲へ直接進めないためです。")}`,
      misunderstandings: [["Secondary IndexのLeafに行全体が入っています。", "通常は条件列と主キーが入り、必要な他の列を読むためClustered Indexへ戻ります。"], ["INDEX(a,b)ならaでもbでも同じ速さです。", "aが左端なので道を選びやすく、bだけでは木の並びを利用しにくいのが基本です。"]],
      questions: [["InnoDBのClustered IndexのLeafに何がありますか。","主キーと行データです。","Clustered IndexのLeafは主KeyだけでRow内容を持ちません。","Clustered IndexのLeafはSecondary Indexの値だけを持ちます。","「主キーと行データです。」が正しいのは、主Keyの順序と本体Rowを一緒に持つため。誤答1の「Clustered IndexのLeafは主KeyだけでRow内容を持ちません。」は本体Rowを持たないとしている。誤答2の「Clustered IndexのLeafはSecondary Indexの値だけを持ちます。」は別IndexのEntryだけとしている。"],["Secondary Indexから本体行へ戻る値は何ですか。","主キーです。","Secondary Indexは主Keyを持たず物理住所だけで戻ります。","本体Rowへは必ずRow番号だけで戻ります。","「主キーです。」が正しいのは、Secondary IndexのEntryが主Keyを持ち、それで本体へ戻るため。誤答1の「Secondary Indexは主Keyを持たず物理住所だけで戻ります。」は主Keyを使う経路を否定している。誤答2の「本体Rowへは必ずRow番号だけで戻ります。」はDBの主Keyを別番号へ置き換えている。"],["Covering Indexとは何ですか。","検索条件と返す列がIndex内にそろい、本体へ戻らず答えられるIndexです。","Covering IndexはIndexを使わず全表走査します。","Covering Indexは書き込み時だけ使います。","「検索条件と返す列がIndex内にそろい、本体へ戻らず答えられるIndexです。」が正しいのは、条件と返す列がIndexにそろい本体Pageへ戻らず答えられるため。誤答1の「Covering IndexはIndexを使わず全表走査します。」はIndexだけで答えられる利点を逆にしている。誤答2の「Covering Indexは書き込み時だけ使います。」は読取と書込の用途を逆にしている。"],["INDEX(a,b)がWHERE bだけで効きにくい理由は何ですか。","木がaを先に、aごとにbを並べているため、aなしではbの範囲へ直接進めないからです。","bがIndexの先頭へ自動で移動します。","bだけなら一つのEntryへ必ず決まります。","「木がaを先に、aごとにbを並べているため、aなしではbの範囲へ直接進めないからです。」が正しいのは、複合Indexはaを先に並べるためbだけでは範囲へ進みにくいから。誤答1の「bがIndexの先頭へ自動で移動します。」は列順が自動変更されるとしている。誤答2の「bだけなら一つのEntryへ必ず決まります。」は条件だけで一意に決まるとしている。"],["複合Indexの列順を決める材料は何ですか。","実際のWHERE条件、選択性、並び替え、返す列、更新コストです。","列順はアルファベット順だけで決めます。","更新負荷は列順と関係ないため考えません。","「実際のWHERE条件、選択性、並び替え、返す列、更新コストです。」が正しいのは、WHERE・値の偏り・ORDER BY・返す列・更新負荷を合わせるため。誤答1の「列順はアルファベット順だけで決めます。」は利用条件を名前順だけにしている。誤答2の「更新負荷は列順と関係ないため考えません。」は書き込み負荷を無視している。"]],
      checks: ["ClusteredとSecondaryのLeaf", "主キーへ戻るLookup", "Covering Index", "Composite Indexの左端列"], search: "Clustered Index Secondary Index Composite Index INDEX(a,b) leftmost prefix lookup covering index InnoDB"
    }),

    chapter({ id: "optimizer-explain", no: 6, shortTitle: "OptimizerとEXPLAIN", title: "OptimizerとExecution Plan：SQLの実行道順", deck: "SQLは命令文の順番どおりに実行されるとは限りません。Parserが意味を読み、Optimizerが統計を見て、実行計画を選ぶ流れをEXPLAINで読みます。" }, {
      reading: "約26分",
      goals: ["Cardinalityが見積もる行数", "SQL Parserと論理的な意味", "Optimizerの候補比較", "EXPLAINのtype・key・rows・Extra"],
      why: `<p>同じSQLでも、データが10行のときと1000万行のときでは最適な道が変わります。SQLをただ上から実行するだけなら、Indexを使うべきか全表走査にするか判断できません。Optimizerが存在しなければ、データ量や分布に合った道を自動で選べません。</p><p>実行計画を知らないと、Indexを追加したのに使われない理由や、JOIN順で急に遅くなった理由を説明できません。</p>`,
      example: `<p><code>SELECT * FROM orders WHERE user_id=7 AND status='open'</code>を考えます。ParserはSQLの単語と式を読み、表・列・条件を認識します。OptimizerはIndexの統計から「user_id=7で何行残るか」「statusでどれだけ減るか」を見積もり、Index Scanや全表走査を比較します。</p><p>実行計画の<code>rows=12</code>は、必ず12行返すという意味ではなく、その段階で読むと予想した行数です。見積もりが外れると、良くない道を選ぶことがあります。</p>
    <h3>予想した行数と実際の行数を見比べる</h3>
    <p>ある条件を満たす注文をOptimizerが100件と見積もったのに、実際は1万件あったとします。少数の候補を処理するつもりで選んだ計画では、表への読み出しやJOINの繰り返しが想定より増えます。</p>
    <p>計画を読むときは、まずどの表・Indexへアクセスするかを見て、次に行数を確認します。実行を伴う計測は安全な検証環境で行い、見積もりと実測の差が大きい最初の段階を探すと、原因を絞れます。</p>`,
      internal: `${diagram("SQLから実行計画", [["SQL", "人が書く意図"], ["Parser", "表・列・条件"], ["Optimizer", "Cardinality・コスト"], ["Plan", "Scan / Join順"], ["Executor", "実際のPage読込"]], "ParserがSQLを理解し、Optimizerが候補のコストを比べ、Executorが選ばれた計画を実行します。")}<h3>Cardinality</h3><p>Cardinalityは文脈によって列の異なる値の数や、条件後に残る行数の見積もりを指します。ここではOptimizerが「この条件で何行くらい残るか」を統計から見積もる意味で使います。値がほぼ一種類なら絞り込みにくく、値が多様なら絞り込みやすい傾向があります。</p><h3>Planの候補</h3><p>Optimizerは全表走査、Index Scan、複数Indexの利用、JOIN順などを候補にします。Pageの読み込み数、CPU比較、Sort、結合方法などをコストとして比べます。最も理論的に美しいSQLではなく、統計上安そうな計画を選びます。</p><h3>EXPLAINの読み方</h3><p><code>type</code>は読み方の分類、<code>possible_keys</code>は候補、<code>key</code>は実際に選んだIndex、<code>rows</code>は見積もり行数、<code>Extra</code>は追加の処理を表します。<code>ALL</code>は全表走査の手掛かり、<code>Using filesort</code>や<code>Using temporary</code>は追加作業の手掛かりです。</p>`,
      web: `<p>APIの遅いSQLでは、まず実際の引数でEXPLAINを確認します。開発データが少ないと全表走査を選んでも、本番の分布ではIndexが選ばれることがあります。逆に本番だけ統計が偏り、見積もりが外れることもあります。</p><p>SQLを書き換える前に、返す行数、JOIN条件、Index列順、統計更新を確認します。第6部のB+Treeの理論だけでなく、RDBではCardinalityと実行計画が道を決めます。</p>`,
      lab: `${experiment("MySQL 検証DB（macOS / Linux）", `${dbSetup}\nCREATE TABLE plan_demo (id INT PRIMARY KEY, category INT, created_at DATE, note VARCHAR(20));\nINSERT INTO plan_demo VALUES (1,10,'2026-01-01','a'),(2,10,'2026-01-02','b'),(3,20,'2026-01-03','c');\nCREATE INDEX idx_plan_category ON plan_demo(category);\nEXPLAIN SELECT * FROM plan_demo WHERE category=10;\nEXPLAIN FORMAT=JSON SELECT * FROM plan_demo WHERE category=10;`, "Optimizerの選択と、JSON形式の詳細計画を確認します。", "type、key、rows、filtered、access_typeを読みます。", "SQLはParserで解釈された後、Cardinalityとコストを使う計画へ変わって実行されると分かります。")}${callout("note", "見積もり", "小さい検証表のrowsは本番と異なります。EXPLAINは「必ずこう実行した」という証拠ではなく、計画と見積もりの観察です。")}`,
      misunderstandings: [["EXPLAINのrowsは、必ず返却される行数です。", "rowsはその段階で読むとOptimizerが見積もった行数で、実際の返却数とは異なります。"], ["SQL文の書いた順番どおりに表を読み、Indexを使うかは固定です。", "Parserの後にOptimizerが候補を比べ、統計やコストに応じて計画を選びます。"]],
      questions: [["Parserの役割は何ですか。","SQLの文字列を読み、表・列・条件などの構造と意味を理解することです。","ParserはDisk Pageを読みIndexの枝を選びます。","ParserはSQL結果をDiskへ書き込みます。","「SQLの文字列を読み、表・列・条件などの構造と意味を理解することです。」が正しいのは、SQL文字列を表・列・条件の内部表現へ変えるため。誤答1の「ParserはDisk Pageを読みIndexの枝を選びます。」はSQL解析とIndex探索を混同している。誤答2の「ParserはSQL結果をDiskへ書き込みます。」は解析処理を保存処理としている。"],["Optimizerが使うCardinalityとは何ですか。","条件後に何行残るかなどを統計から見積もる値です。","CardinalityはSQL文字列の長さです。","Cardinalityは実際に読み終えたRow数だけです。","「条件後に何行残るかなどを統計から見積もる値です。」が正しいのは、条件後に残るRow数を統計から見積もる値だから。誤答1の「CardinalityはSQL文字列の長さです。」は行数の見積りを文字数としている。誤答2の「Cardinalityは実際に読み終えたRow数だけです。」は予測値を実測値だけに限定している。"],["EXPLAINのkeyは何を示しますか。","実行計画で実際に選ばれたIndexです。","keyはPrimary Key定義だけを示します。","keyは最初に読んだColumn名だけを示します。","「実行計画で実際に選ばれたIndexです。」が正しいのは、実行計画で選ばれたIndexを示すため。誤答1の「keyはPrimary Key定義だけを示します。」は選んだIndexを定義情報だけにしている。誤答2の「keyは最初に読んだColumn名だけを示します。」はIndexをColumn一つに限定している。"],["EXPLAINのrowsは何ですか。","その段階で読むと見積もった行数です。","rowsは実際に返したRow数を必ず示します。","rowsはTableの総Page数だけを示します。","「その段階で読むと見積もった行数です。」が正しいのは、その段階で読むと予想したRow数を示すため。誤答1の「rowsは実際に返したRow数を必ず示します。」は見積りを実測結果としている。誤答2の「rowsはTableの総Page数だけを示します。」はRow数をPage数としている。"],["type=ALLから何を疑えますか。","全表走査になっている可能性です。","type=ALLなら最適なIndex検索です。","type=ALLはSQL構文エラーを示します。","「全表走査になっている可能性です。」が正しいのは、Indexを使わず全Rowを調べる可能性があるため。誤答1の「type=ALLなら最適なIndex検索です。」は全表走査を良い計画としている。誤答2の「type=ALLはSQL構文エラーを示します。」はアクセス方式と構文エラーを混同している。"],["小さい検証表の計画を本番へそのまま信じにくい理由は何ですか。","データ量や値の分布が異なり、Cardinalityとコストが変わるからです。","小さい表のrows見積りは本番でも必ず同じです。","本番のCardinalityはデータ量が増えても一定です。","「データ量や値の分布が異なり、Cardinalityとコストが変わるからです。」が正しいのは、データ量や値の分布が本番と違い、費用の見積りが変わるため。誤答1の「小さい表のrows見積りは本番でも必ず同じです。」は検証環境と本番の分布差を無視している。誤答2の「本番のCardinalityはデータ量が増えても一定です。」はデータ増加で見積りが変わらないとしている。"]],
      checks: ["Cardinalityの見積もり", "Parser・Optimizer・Executor", "Execution Planの候補", "EXPLAINの主要列"], search: "Optimizer Query Parser Cardinality execution plan EXPLAIN type possible_keys key rows filtered Extra filesort temporary cost"
    }),

    chapter({ id: "buffer-pool", no: 7, shortTitle: "Buffer Pool", title: "Buffer Pool：SELECTは毎回Diskか", deck: "答えは『毎回ではありません』です。InnoDBがPageをBuffer Poolへ置き、再利用する流れと、メモリ不足やCache MissでDiskへ行く条件を整理します。" }, {
      reading: "約24分",
      goals: ["Buffer PoolのPage Cacheとしての役割", "Cache HitとCache Miss", "Dirty PageとFlush", "SELECTが毎回Diskへ行くわけではない理由"],
      why: `<p>SELECTのたびにDiskへ行くと、同じ設定画面やユーザー情報を読むだけで毎回ストレージ待ちになります。Buffer Poolがなければ、頻繁に使うPageをメモリへ再利用できず、DBの速度が大きく落ちます。</p><p>ただしメモリは有限です。Buffer Poolが小さい、別のPageに追い出された、初めて読む、という場合はDiskから読む必要があります。「DBは常にメモリ」「DBは常にDisk」のどちらも正しくありません。</p>${callout("important", "指定疑問への答え", "SELECTは毎回Diskへ行くわけではありません。必要なInnoDB PageがBuffer Poolにあればメモリから返り、なければDisk I/Oで読み込みます。")}`,
      example: `<p>最初の<code>SELECT * FROM users WHERE id=7</code>で、対象のPageがBuffer Poolにないとします。InnoDBはDiskからPageを読み、Buffer Poolへ置いて行を返します。同じPageにある別のidをすぐ読むと、Diskへ行かずメモリから返る可能性があります。</p><p>UPDATEでPageを変えると、メモリ上のPageはDirty Pageになります。Commitが成功しても、毎回その場で表Page全体をDiskへ書くとは限りません。InnoDBはRedo Logなどで耐久性を確保し、Dirty Pageを後でFlushします。</p>
    <h3>読み出しが速いのに更新が詰まる場合</h3>
    <p>よく使う商品PageがすでにBuffer Poolにあり、検索はメモリ上で済むとします。更新によってPageが変わると、メモリ上のPageは後で書き出す必要があります。更新が続いて書き出しが追いつかなければ、読み出しのヒット率が高くても待ち時間が増える場合があります。</p>
    <p>Buffer Poolを見るときは、読み出しで再利用できているかと、変更したPageを書き出せているかを分けます。どちらで待ちが増えているかによって、確認する指標が変わります。</p>`,
      internal: `<figure class="concept-figure" aria-labelledby="buffer-pool-paths-title">
        <h3 class="visual-title" id="buffer-pool-paths-title">SELECTとBuffer Pool</h3>
        <p>主キー7の行を読むとき、必要なページがBuffer Poolにあるかを確かめます。下の二つは、その確認から分かれる道です。</p>
        <div class="visual-compare">
          <div data-visual-role="store"><strong>Hit（ページがある）</strong><p>メモリ内のページから行を読みます。</p></div>
          <div data-visual-role="wait"><strong>Miss（ページがない）</strong><p>ストレージからページを読み込んでBuffer Poolに置き、それから行を読みます。</p></div>
        </div>
        <figcaption class="visual-caption">Missで取り込んだページがメモリに残っていれば、次の読み出しではHitになります。</figcaption>
      </figure><h3>HitとMiss</h3><p>必要なPageがBuffer Poolにある状態をHit、ない状態をMissと呼びます。Hit率が高いほどDisk I/Oを減らせますが、Hit率だけでSQLが速いと断言はできません。読み込むPage数やCPU、ロック待ちも関係します。</p><h3>置き換え</h3><p>新しいPageを置く場所が足りないと、あまり使われていないPageを追い出します。追い出すPageがDirtyなら、変更を安全に書き出してから再利用します。頻繁に使う表が大きすぎると、互いにPageを追い出し合う可能性があります。</p><h3>DB CacheとOS Cacheの重なり</h3><p>InnoDBが管理するBuffer Poolのほか、OSやストレージにもCacheがあります。第2部のPage Cacheとの関係で、同じデータが複数層に存在することがあります。どのCacheがHitしたかを混同せず、DBの読み取り量とDisk I/Oを別に見ます。</p>`,
      web: `<p>本番のBuffer Poolサイズは、DB専用メモリ、同居するアプリ、接続数、OSの余裕を考えて決めます。大きければよいだけではなく、Swapを起こさないことが重要です。</p><p>「再起動後だけ遅い」のはBuffer Poolが空で、必要なPageを読み込むWarm-upが起きている可能性があります。遅いSQLの調査では、EXPLAINと合わせて読み込んだPage、Buffer Poolの状態、Disk latencyを確認します。</p>`,
      lab: `${experiment("MySQL 検証DB（macOS / Linux）", `${dbSetup}\nCREATE TABLE buffer_demo (id INT PRIMARY KEY, note VARCHAR(40)) ENGINE=InnoDB;\nINSERT INTO buffer_demo VALUES (1, 'sample');\nSHOW GLOBAL STATUS LIKE 'Innodb_buffer_pool_read%';\nSELECT * FROM buffer_demo WHERE id=1;\nSHOW GLOBAL STATUS LIKE 'Innodb_buffer_pool_read%';\nSELECT * FROM buffer_demo WHERE id=1;\nSHOW GLOBAL STATUS LIKE 'Innodb_buffer_pool_read%';`, "Buffer Poolの読み込みカウンタを、同じSELECTの前後で観察します。", "Innodb_buffer_pool_read_requestsとInnodb_buffer_pool_readsの増え方に注目します。", "read_requestsは論理的な読み取り要求、readsはBuffer Poolに無く新たに読み込んだ回数です。作成した直後のページはすでにメモリにあり、最初からreadsが増えない場合があります。")}${callout("note", "環境差", "検証表が小さい、別のSQLが同じPageを読んでいるなどでカウンタの差は変わります。値を絶対視せず、Cache Hitという考え方を観察します。")}`,
      misunderstandings: [["SELECTは必ずDiskから最新の行を読みます。", "Buffer PoolにあるPageを読み、InnoDBの一貫性ルールに従って必要なVersionを返します。"], ["Buffer PoolのHit率が高ければ、どんなSQLも速いです。", "Hitしても読むPage数、CPU、Join、Lock待ちなどが大きければ遅くなります。"]],
      questions: [["Buffer Poolの役割は何ですか。","InnoDBのPageをメモリへ保持し、再利用してDisk I/Oを減らすことです。","Buffer PoolはSQL文字列だけを保持します。","Buffer Poolは主Keyの番号だけを保持します。","「InnoDBのPageをメモリへ保持し、再利用してDisk I/Oを減らすことです。」が正しいのは、InnoDBのPageをメモリに保持して再利用するため。誤答1の「Buffer PoolはSQL文字列だけを保持します。」はDBのPageではなくSQL文だけを保存するとしている。誤答2の「Buffer Poolは主Keyの番号だけを保持します。」はPageの内容をKey番号だけに狭めている。"],["Cache Hitとは何ですか。","必要なPageがBuffer Poolにあり、Diskから新たに読まずに済むことです。","Cache HitはPageがなくDisk読込が始まる状態です。","Cache HitはSQLが実行されず空の結果になる状態です。","「必要なPageがBuffer Poolにあり、Diskから新たに読まずに済むことです。」が正しいのは、必要なPageがBuffer PoolにありDisk読込なしで使えるため。誤答1の「Cache HitはPageがなくDisk読込が始まる状態です。」はHitとMissを逆にしている。誤答2の「Cache HitはSQLが実行されず空の結果になる状態です。」はCache Hitを未実行状態としている。"],["Cache Missでは何が起きますか。","必要なPageをDiskなどからBuffer Poolへ読み込みます。","Cache Missでは別の古いPageを削除するだけです。","Cache MissではDiskを読まず空の結果を返します。","「必要なPageをDiskなどからBuffer Poolへ読み込みます。」が正しいのは、必要なPageをDiskから読みBuffer Poolへ載せるため。誤答1の「Cache Missでは別の古いPageを削除するだけです。」は読込を置換だけの処理にしている。誤答2の「Cache MissではDiskを読まず空の結果を返します。」はデータ取得を空結果としている。"],["UPDATE後のDirty Pageとは何ですか。","メモリ上では変更済みですが、保存先への書き戻しが残るPageです。","Dirty PageはBuffer PoolとDiskが完全に一致します。","Dirty Pageは読み取り専用で変更できません。","「メモリ上では変更済みですが、保存先への書き戻しが残るPageです。」が正しいのは、メモリ上の変更が保存先へまだ書き戻されていないため。誤答1の「Dirty PageはBuffer PoolとDiskが完全に一致します。」は変更差分がない状態にしている。誤答2の「Dirty Pageは読み取り専用で変更できません。」は書込禁止の属性と混同している。"],["SELECTは毎回Diskへ行きますか。","いいえ。必要なPageがBuffer Poolにあればメモリから返ります。","SELECTは必ずDiskへ行きBuffer Poolを使いません。","SELECTはDiskを使わず保存場所を確認しません。","「いいえ。必要なPageがBuffer Poolにあればメモリから返ります。」が正しいのは、必要なPageがBuffer Poolにあればメモリから返せるため。誤答1の「SELECTは必ずDiskへ行きBuffer Poolを使いません。」はCache利用を否定している。誤答2の「SELECTはDiskを使わず保存場所を確認しません。」は読取処理が保存場所を見ないとしている。"],["再起動直後に遅くなりやすい理由は何ですか。","Buffer Poolが空に近く、必要なPageをDiskから読み直すためです。","再起動直後は全PageがCPUレジスタへ移ります。","再起動直後はIndexが自動削除されます。","「Buffer Poolが空に近く、必要なPageをDiskから読み直すためです。」が正しいのは、Buffer Poolが空に近く必要なPageをDiskから読み直すため。誤答1の「再起動直後は全PageがCPUレジスタへ移ります。」はメモリCacheをレジスタへ移すとしている。誤答2の「再起動直後はIndexが自動削除されます。」は再起動でIndexが消えるとしている。"]],
      checks: ["Buffer Poolの役割", "Hit・Miss", "Dirty PageとFlush", "SELECTとDisk I/Oの関係", "第2部Page Cacheとの差"], search: "InnoDB Buffer Pool cache hit miss Dirty Page Flush SELECT disk innodb_buffer_pool_read_requests innodb_buffer_pool_reads"
    }),

    chapter({ id: "transaction-acid", no: 8, shortTitle: "TransactionとACID", title: "TransactionとACID：途中を見せないまとまり", deck: "銀行口座の送金を、引き落としだけ成功させてはいけません。TransactionとACIDが、複数の変更を一つの仕事として守る仕組みです。" }, {
      reading: "約24分",
      goals: ["Transactionの開始・Commit・Rollback", "Atomicity・Consistency・Isolation・Durability", "Isolation Levelの見え方", "途中状態を他Transactionへ見せない理由"],
      why: `<p>口座Aから100円を引き、口座Bへ100円を足す送金を考えます。引き落とし後に電源が切れ、入金がなければ100円が消えます。Transactionがなければ、関連する変更を一つの成功・失敗として扱いにくくなります。</p><p>ACIDは、途中で失敗しても壊れた状態を残しにくくし、同時実行でも互いの途中経過を勝手に読ませず、確定した変更を障害後も守るための性質です。</p>`,
      example: `<p><code>START TRANSACTION</code>で始め、Aを<code>-100</code>、Bを<code>+100</code>にし、両方成功したら<code>COMMIT</code>します。途中でエラーなら<code>ROLLBACK</code>でTransaction開始前へ戻します。</p><p>Atomicityは全部か無か、Consistencyは制約を守る、Isolationは同時処理の見え方を分離する、DurabilityはCommit後の変更を障害後も残す性質です。どれも「速さ」だけでなく、正しい状態を守るために必要です。</p>
    <h3>送金の途中で失敗したら何が残るか</h3>
    <p>残高500円のAから残高200円のBへ100円を送ります。</p>
    <ul><li><strong>両方の更新が成功</strong>してCOMMITすると、Aは400円、Bは300円です。</li>
      <li><strong>Aから引いた直後に失敗</strong>してROLLBACKすると、Aは500円、Bは200円に戻ります。</li></ul>
    <p>どちらの結果でも、お金を移しただけなので合計は700円です。COMMITとROLLBACKは二つの更新をまとめます。残高不足の拒否など、送金に必要な業務上の条件も処理側で守る必要があります。</p>`,
      internal: `${diagram("送金Transaction", [["BEGIN", "仕事の境界"], ["A -100", "未確定"], ["B +100", "未確定"], ["COMMIT", "全部確定"], ["障害", "ROLLBACK"]], "Commit前の変更は他の処理へ見せないようにし、成功ならまとまりとして確定、失敗なら戻します。")}<h3>AtomicityとConsistency</h3><p>Atomicityは、二つのUPDATEの片方だけを成功にしない性質です。ConsistencyはPrimary KeyやForeign Key、CHECKなどの制約と業務ルールを守り、DBを許された状態から許された状態へ移す性質です。</p><h3>Isolation</h3><p>複数のTransactionが同じ行を読む・書くと、相手の途中変更をどこまで見せるか決める必要があります。Isolation Levelはその見え方と、ロックや待ちの強さの調整です。</p><h3>Durability</h3><p>Commitが返った後に電源が落ちても、再起動後に確定データを復元できるよう、InnoDBはRedo Logなどへ記録します。表Pageを毎回すぐ書き終えることだけがDurabilityではありません。</p>`,
      web: `<p>Webの注文APIでは、在庫を減らす、注文を作る、支払い状態を記録する処理をTransactionへ含める範囲を設計します。外部決済サービスの返事までDB Transactionを保持すると長いロックになりやすいため、状態遷移や再試行も合わせて考えます。</p><p>Isolationを強くすれば常に良いわけではなく、同時実行数や待ち時間が増えることがあります。第9部で扱うMVCCとLockを使い、必要な整合性と性能を選びます。</p>`,
      lab: `${experiment("MySQL 検証DB（macOS / Linux）", `${dbSetup}\nCREATE TABLE account_demo (id INT PRIMARY KEY, balance INT);\nINSERT INTO account_demo VALUES (1,1000),(2,500);\nSTART TRANSACTION;\nUPDATE account_demo SET balance=balance-100 WHERE id=1;\nUPDATE account_demo SET balance=balance+100 WHERE id=2;\nSELECT * FROM account_demo;\nROLLBACK;\nSELECT * FROM account_demo;`, "Commit前の変更を確認し、Rollbackで元へ戻します。", "Transaction中のSELECTとRollback後のbalanceに注目します。", "複数UPDATEを一つの作業として取り消せることが分かります。")}${experiment("MySQL 検証DB（macOS / Linux）", `START TRANSACTION;\nUPDATE account_demo SET balance=balance+1 WHERE id=1;\nCOMMIT;\nSELECT * FROM account_demo;`, "Commitすると変更が確定する境界を確認します。", "COMMITの前後で別Sessionから見える値を比較します。", "Transactionの確定はSQL一文の終了ではなく、Commitという境界で決まると分かります。")}`,
      misunderstandings: [["UPDATE文が成功した時点で、誰から見ても確定です。", "Transaction中なら、Commitまで他Transactionから見えない、またはIsolationに応じた見え方になります。"], ["ACIDのDは、表PageをCommitの瞬間に全部Diskへ書く意味です。", "確定内容を障害後に復元できるようログなどで耐久性を作る性質です。"]],
      questions: [["TransactionのCommitは何をしますか。","まとまった変更を成功として確定します。","Commitは未確定の変更をすべて取り消します。","Commitは次のTransactionを自動開始します。","「まとまった変更を成功として確定します。」が正しいのは、まとまった変更を成功として確定するため。誤答1の「Commitは未確定の変更をすべて取り消します。」は確定と取消を逆にしている。誤答2の「Commitは次のTransactionを自動開始します。」はTransaction開始を自動化する操作としている。"],["Rollbackは何をしますか。","Transactionの変更を取り消し、開始前の状態へ戻します。","Rollbackは変更を確定して他Sessionへ公開します。","RollbackはDBの表そのものを削除します。","「Transactionの変更を取り消し、開始前の状態へ戻します。」が正しいのは、Transaction中の変更を取り消し開始前の状態へ戻すため。誤答1の「Rollbackは変更を確定して他Sessionへ公開します。」は取消を確定としている。誤答2の「RollbackはDBの表そのものを削除します。」は行の変更と表の削除を混同している。"],["ACIDのAは何ですか。","Atomicityで、処理を全部成功または全部失敗として扱う性質です。","AはAccessで読み取り専用を意味します。","AはAvailabilityでReplica台数だけを意味します。","「Atomicityで、処理を全部成功または全部失敗として扱う性質です。」が正しいのは、Atomicityが複数変更を全部成功または全部失敗として扱うため。誤答1の「AはAccessで読み取り専用を意味します。」は頭文字を別のDB用語にしている。誤答2の「AはAvailabilityでReplica台数だけを意味します。」はAtomicityのまとまりをReplica台数としている。"],["ACIDのIは何ですか。","Isolationで、同時Transactionの途中状態の見え方を分離する性質です。","IはIndexで検索用の木だけを指します。","IはInputでSQL入力値の形式だけを指します。","「Isolationで、同時Transactionの途中状態の見え方を分離する性質です。」が正しいのは、Isolationが同時Transactionから途中変更をどう見せるかを分けるため。誤答1の「IはIndexで検索用の木だけを指します。」はACIDのIをIndexの機能としている。誤答2の「IはInputでSQL入力値の形式だけを指します。」は入力形式の検査としている。"],["Durabilityが必要な理由は何ですか。","Commit後の確定結果を障害や再起動の後も守るためです。","Durabilityは未確定値を必ず公開します。","DurabilityはSELECTの速度だけを保証します。","「Commit後の確定結果を障害や再起動の後も守るためです。」が正しいのは、Commit後の確定結果を障害や再起動後にも復元するため。誤答1の「Durabilityは未確定値を必ず公開します。」は確定結果の保持を公開操作としている。誤答2の「DurabilityはSELECTの速度だけを保証します。」は耐久性を読取速度としている。"],["Isolation Levelを強くすると起き得ることは何ですか。","同時実行の見え方は厳密になりますが、Lock待ちなどの費用が増えることがあります。","Isolationを強くすると全Lockが不要になります。","Isolationを強くすると同時実行の見え方が自由になります。","「同時実行の見え方は厳密になりますが、Lock待ちなどの費用が増えることがあります。」が正しいのは、見え方は厳密になる一方Lock取得や待ちが増えることがあるため。誤答1の「Isolationを強くすると全Lockが不要になります。」は厳密さとLock負荷を逆にしている。誤答2の「Isolationを強くすると同時実行の見え方が自由になります。」は分離を弱める説明になっている。"]],
      checks: ["Transactionの境界", "RollbackとCommit", "ACID四性質", "Isolation Levelと性能の調整"], search: "Transaction START TRANSACTION COMMIT ROLLBACK ACID Atomicity Consistency Isolation Durability isolation level InnoDB"
    }),

    chapter({ id: "mvcc-lock-deadlock", no: 9, shortTitle: "MVCCとLock", title: "MVCC・Snapshot・Lock：同時実行の見え方", deck: "COMMIT前のデータはどこにあるのでしょうか。InnoDBは古いVersionを残し、Snapshotで読み、書き込みにはLockを使います。Deadlockの発生条件まで追います。" }, {
      reading: "約28分",
      goals: ["MVCCが複数Versionを持つ理由", "Snapshot Readと現在の値", "Lockが書き込みを直列化する流れ", "Deadlockの検出と再試行"],
      why: `<p>Transaction Aが商品数を変更している途中に、Transaction BのSELECTが待たされると、読み取りが多いWebサービスは止まりやすくなります。逆に途中の未確定値を見せると、まだ失敗するかもしれない在庫を売る判断につながります。読み取りと書き込みの待ちを調整する仕組みが必要です。</p><p>MVCC（Multi-Version Concurrency Control）は、行のVersionを使って読み取りのSnapshotを作ります。Lockは同じ行を安全に更新するための待ちです。両者を区別すると、なぜSELECTが書き込みを待たない場合があるか分かります。</p>${callout("important", "指定疑問への答え", "COMMIT前の新しい値は、主にBuffer Pool上の変更PageとUndo情報にあり、確定版ではありません。別TransactionのSnapshot ReadはUndoを使って自分の見える時点の古いVersionを組み立てます。")}`,
      example: `<p>Transaction Aが残高を1000から900へ変更してまだCommitしていないとします。変更PageはInnoDBのメモリ上にあり、Undoには変更前の1000へ戻す情報があります。Transaction Bが通常のSnapshot Readをすると、Aの未Commit 900ではなく、見える時点の1000を読みます。</p><p>AがCommitした後に新しいSnapshotを作れば、Bは900を見ます。Bが同じ行を更新する現在値読み取りを行うと、Lockを待ち、最新状態を確認することがあります。</p>
    <h3>同じ行でも待つ読み方と待たずに読める読み方</h3>
    <p>図の値100がある行をAが80へ変更し、まだ確定していないとします。</p>
    <ul><li><strong>Snapshot Read</strong>では、Bが参照するSnapshotで80が見えなければ、Undoの情報から見えてよい旧値100を読みます。</li>
      <li><strong>ロックを取って読む操作</strong>では、CがAのロック解放を待ちます。Aが確定してから取得すると、80を読めます。</li></ul>
    <p>CがAを一方向に待つだけなら、Aが処理を終えれば進めます。AもCの持つ別のロックを待って互いに進めなくなったとき、待ちの輪ができてDeadlockになります。</p>`,
      internal: `${mvccFigure()}<h3>段階1：更新とUndo</h3><p>Transaction Aが行を更新すると、新しい値と、更新前へ戻るためのUndoの手掛かりができます。まだCOMMITしていない値を、別Transactionへそのまま見せるわけではありません。</p><h3>段階2：Snapshot Read</h3><p>通常のConsistent Readは、Snapshotの時点で見えてよいVersionを選びます。新しい値がまだ見えなければUndoをたどって旧Versionを組み立てます。古いVersionは永遠に残らず、不要になるとPurgingされます。</p><h3>段階3：Locking Readと更新</h3><p><code>SELECT ... FOR UPDATE</code>やUPDATEは、現在の値を使って更新するためLockを取ります。他のTransactionが先にLockを持っていれば、旧Versionを読む代わりに解放を待つ場合があります。</p><h3>段階4：Deadlock</h3><p>Aが行1をLockして行2を待ち、Bが行2をLockして行1を待つと待ちが円になります。InnoDBは一方をRollbackして円を切ります。アプリは安全に再試行し、Lock取得順をそろえて発生を減らします。</p>`,
      web: `<p>注文処理で「在庫を読む→減らす」を別SQLにすると、同時注文の競合が起きます。必要なら一つのTransactionで現在値をLockし、条件付きUPDATEで残数を守ります。Transactionを長くしすぎるとLock待ちとDeadlockの範囲が増えます。</p><p>MVCCは「全てのSELECTが古い値」という意味ではありません。Isolation Level、Snapshotを作る時点、FOR UPDATEの有無で見え方が変わります。第9部のMutexなどアプリ内並行性と同様、共有データへの順番を設計します。</p>`,
      lab: `<p>端末を二つ開きます。まず端末Aで更新を始め、<code>COMMIT</code>せずに待ちます。続けて端末Bで二種類の読み取りを比較します。</p>
      ${experiment("端末A・更新を未確定のままにする", `${dbSetup}
CREATE TABLE mvcc_demo (id INT PRIMARY KEY, value INT) ENGINE=InnoDB;
INSERT INTO mvcc_demo VALUES (1, 100);
START TRANSACTION;
UPDATE mvcc_demo SET value = 80 WHERE id = 1;`, "行を100から80へ更新し、Lockを保持します。", "端末AはUPDATEが終わっても、COMMITを実行するまでは変更を確定しません。", "端末Bから見る同じ行には、確定済みの100と未確定の80があります。")}
      ${experiment("端末B・通常の読み取りとFOR UPDATEを比較", `mysql -uroot -p lesson_rdb
SET SESSION TRANSACTION ISOLATION LEVEL READ COMMITTED;
SET SESSION innodb_lock_wait_timeout = 3;
START TRANSACTION;
SELECT value FROM mvcc_demo WHERE id = 1;
SELECT value FROM mvcc_demo WHERE id = 1 FOR UPDATE;
ROLLBACK;`, "同じ条件で、読み取り方法だけを変えます。", "通常のSELECTでは100が返ります。FOR UPDATEはAが持つLockを待ち、約3秒で待ち時間の上限に達します。", "一つの行でも、確定済みの版を読める処理と、Lockを取る必要がある処理があることを確認できます。")}
      <p>最後に端末Aで <code>COMMIT;</code> を実行し、端末Bで通常のSELECTをもう一度実行します。今度は80が返ります。</p>`,
      misunderstandings: [["COMMIT前の値は、どこにも存在しません。", "Buffer Pool上の変更PageやUndoといったInnoDB内部の状態には存在しますが、他Transactionの確定値としては扱われません。"], ["MVCCがあればDeadlockは起きません。", "MVCCは主に読み取りVersionの仕組みで、複数Transactionの書き込みLockが循環すればDeadlockは起きます。"]],
      questions: [["MVCCの目的は何ですか。","複数VersionとSnapshotで、読み取りを他Transactionの未Commit変更から分離することです。","MVCCは全ての書き込みを一つずつ停止します。","MVCCは古いVersionを消して常に最新値だけ返します。","「複数VersionとSnapshotで、読み取りを他Transactionの未Commit変更から分離することです。」が正しいのは、複数VersionとSnapshotで未Commit変更を読み取りから分けるため。誤答1の「MVCCは全ての書き込みを一つずつ停止します。」は読み取りのVersion管理を全書込停止としている。誤答2の「MVCCは古いVersionを消して常に最新値だけ返します。」は古いVersionを使う仕組みを逆にしている。"],["COMMIT前の新しい値はどこにありますか。","主にBuffer Pool上の変更PageとUndoへ戻る情報など、InnoDB内部の状態にあります。","未Commit値はMemoryにもLogにも存在しません。","未Commit値は直ちに全Replicaへ確定コピーされます。","「主にBuffer Pool上の変更PageとUndoへ戻る情報など、InnoDB内部の状態にあります。」が正しいのは、変更PageとUndo情報がInnoDB内部にあり確定値としては扱わないため。誤答1の「未Commit値はMemoryにもLogにも存在しません。」は内部状態への存在を否定している。誤答2の「未Commit値は直ちに全Replicaへ確定コピーされます。」は確定前にReplicaへ広がるとしている。"],["Snapshot Readは何を使いますか。","Transactionの見える時点に合うVersionを使います。","Snapshot Readは常に最新の未Commit値を選びます。","Snapshot Readは必ずLockを取得して他Transactionを止めます。","「Transactionの見える時点に合うVersionを使います。」が正しいのは、Snapshot時点で見えるVersionを選ぶため。誤答1の「Snapshot Readは常に最新の未Commit値を選びます。」は未Commit値を優先する読み方としている。誤答2の「Snapshot Readは必ずLockを取得して他Transactionを止めます。」はLocking Readの性質と混同している。"],["SELECT ... FOR UPDATEの特徴は何ですか。","現在値を読み、更新のための行Lockを取得して競合を待つことがあります。","FOR UPDATEは古いSnapshotだけを読みLockを取りません。","FOR UPDATEはSELECT結果を自動Commitします。","「現在値を読み、更新のための行Lockを取得して競合を待つことがあります。」が正しいのは、現在値を読み更新用の行Lockを取得し競合時に待つことがあるため。誤答1の「FOR UPDATEは古いSnapshotだけを読みLockを取りません。」は更新用Lockを否定している。誤答2の「FOR UPDATEはSELECT結果を自動Commitします。」は読取文にCommit作用を加えている。"],["Deadlockはどのように起きますか。","Transaction同士が互いに相手のLock解放を待つ循環ができると起きます。","一つのTransactionが全Lockをすぐ解放すると起きます。","Deadlockは読み取りだけで常に起きます。","「Transaction同士が互いに相手のLock解放を待つ循環ができると起きます。」が正しいのは、Transactionが互いに相手のLock解放を待つ円ができるため。誤答1の「一つのTransactionが全Lockをすぐ解放すると起きます。」は循環待ちではなく即時解放を原因にしている。誤答2の「Deadlockは読み取りだけで常に起きます。」は書き込みの順序を無関係としている。"],["Deadlock発生時にInnoDBが行うことは何ですか。","一方のTransactionをRollbackして循環を解き、もう一方を進めます。","InnoDBは全Transactionを永久停止します。","InnoDBはDeadlockした双方をCommitします。","「一方のTransactionをRollbackして循環を解き、もう一方を進めます。」が正しいのは、一方をRollbackして待ちの円を切り他方を進めるため。誤答1の「InnoDBは全Transactionを永久停止します。」は復旧動作を停止としている。誤答2の「InnoDBはDeadlockした双方をCommitします。」は未完了の両方を確定するとしている。"],["Deadlockを減らす方法は何ですか。","複数行のLock取得順をそろえ、Transactionを短くし、必要なら安全に再試行します。","全Lockを無期限に保持すれば防げます。","再試行を禁止しLock取得順をそろえないようにします。","「複数行のLock取得順をそろえ、Transactionを短くし、必要なら安全に再試行します。」が正しいのは、Lock取得順をそろえTransactionを短くし安全に再試行するため。誤答1の「全Lockを無期限に保持すれば防げます。」は長時間Lockを保持する方法としている。誤答2の「再試行を禁止しLock取得順をそろえないようにします。」は再試行と順序統一を避けている。"]],
      checks: ["MVCCとUndo", "Snapshot Read", "Lockを取る読み取り", "COMMIT前データの所在", "Deadlockと再試行"], search: "MVCC Multi-Version Snapshot Undo version Buffer Pool SELECT FOR UPDATE lock deadlock InnoDB isolation consistent read"
    }),

    chapter({ id: "redo-undo-wal-replication", no: 10, shortTitle: "Redo・Undo・WAL・Replication", title: "Redo・Undo・WAL・Replication：障害と複製への備え", deck: "DBは変更した行をすぐ全部書き終えるまで待つのではなく、Redo・Undo・WALで復旧できる記録を残します。Crash RecoveryとReplicationを一つの流れで理解します。" }, {
      reading: "約28分",
      goals: ["Redo LogとUndoの目的の違い", "WALがCommitを先に記録する理由", "Crash RecoveryのAnalysis・Redo・Undo", "ReplicationのSource・Replicaと遅延"],
      why: `<p>UPDATEのたびに表の全PageをDiskへ同期すると、書き込みが遅くなります。しかし変更をメモリだけに残して電源が落ちると、Commit済みデータを失います。Logがなければ、速さと耐久性を両立しにくくなります。</p><p>さらに一台のDBだけが壊れると、サービス全体が止まります。Replicationで別のDBへ変更を送り、読み取りや障害切替に備えます。ただし複製先が常に同じ瞬間とは限らず、遅延を設計へ入れる必要があります。</p>`,
      example: `<p>InnoDBが残高を900へ変更したとします。まずUndoは、RollbackやMVCCで変更前へ戻るための情報を持ちます。Redo Logは、変更後のPage操作を再起動後にやり直すための情報です。WAL（Write-Ahead Logging）は、データPageを確定させる前に必要なLogを安全な順で書く考え方です。</p><p>Commit後に電源が落ち、データPageがまだ古くても、再起動時にRedoを適用すれば900を復元できます。Commit前に落ちた変更はUndoなどで取り消します。</p>
    <h3>二種類のログを障害復旧で見分ける</h3>
    <p>確定済みの更新がデータPageへ反映される前に停止したら、再起動後にその変更を復元する必要があります。Redoは変更をやり直す手掛かりです。反対に、確定していないTransactionの変更を取り消すには、Undoが変更前の状態をたどる手掛かりになります。</p>
    <p>別サーバーへの複製は、障害からのローカル復旧とは別の段階です。あるサーバーでのCOMMITを確認しただけでは、読み取り先のReplicaまで変更が届いたかは分かりません。</p>`,
      internal: `${diagram("Crash Recovery", [["変更", "Buffer Pool"], ["Undo", "戻す手掛かり"], ["Redo/WAL", "先にLog保存"], ["Crash", "電源断"], ["Recovery", "Redo→Undo"], ["DB", "確定状態"]], "再起動時にLogから確定変更を再適用し、未Commitの変更を取り消して、許された状態へ戻します。")}<h3>段階1：RedoとUndo</h3><p>Redoは「確定した変更をもう一度適用する」ための記録です。Undoは「変更前へ戻る」ための情報で、RollbackやMVCCの旧Versionにも使われます。Redoは前へ進め、Undoは戻すものです。</p><h3>段階2：WALの書き込み順</h3><p>変更後のData Pageより先に、復元に必要なRedo Logを永続的な場所へ書きます。Data Pageが古いままCrashしても、先に残したLogから変更を再現できます。WALは製品名ではなく、この『記録を先にする』考え方です。</p><h3>段階3：Crash Recovery</h3><p>再起動時はLogを調べ、必要な確定変更をRedoし、未完了Transactionの変更をUndoします。細かな手順は実装ごとに違いますが、目的は『COMMIT済みは残し、未COMMITは見せない』ことです。</p><h3>段階4：Replication</h3><p>Sourceが変更をbinlogなどへ記録し、Replicaが受け取って適用します。届いて適用されるまでの遅れがReplication Lagです。Crash Recoveryは同じDBを直し、Replicationは別のDBへ変更を運ぶ仕組みなので、役割を分けます。</p>`,
      web: `<p>Webアプリでは、DBのCommit成功を利用者へ返す条件と、Replicaへ届いたことを待つ条件を分けます。注文直後の注文詳細はPrimaryから読む、分析画面は遅延を許してReplicaから読む、という設計ができます。</p><p>バックアップはReplicationの代わりではありません。Replicaで誤って削除した変更も複製される可能性があるため、時点復旧できるBackup、Log保持、復旧訓練が必要です。第9部の並行性と同じく、障害時の順番と再試行を考えます。</p>`,
      lab: `${experiment("MySQL 検証DB（macOS / Linux）", `${dbSetup}\nSHOW VARIABLES LIKE 'innodb_log%';\nSHOW VARIABLES LIKE 'innodb_undo%';\nSHOW ENGINE INNODB STATUS\\G;\nSELECT * FROM performance_schema.log_status;`, "Redo Log関連の設定とInnoDB状態を安全に読み取ります。", "innodb_log_file_size、log_status、History list lengthなど、環境に存在する項目を確認します。", "表Pageとは別に、変更を復旧するLogとUndoの領域があると分かります。")}${experiment("MySQL 検証DB（macOS / Linux）", `SHOW VARIABLES LIKE 'log_bin';\nSHOW BINARY LOGS;\nSHOW MASTER STATUS;\nSHOW REPLICA STATUS\\G;`, "binlogとReplicationの設定・遅延を確認します。", "log_bin、File、Position、Replica_IO_Running、Seconds_Behind_Sourceなどの存在と値に注目します。", "Replicationは別DBへ変更を運ぶ仕組みで、設定や適用の遅れを監視する必要があると分かります。")}${callout("warning", "検証環境", "SHOW REPLICA STATUSが空でも故障とは限りません。Replicaを設定していない検証DBでは正常です。実験では設定変更や停止を行わず、読み取りだけにします。")}`,
      misunderstandings: [["RedoとUndoは同じ目的のLogです。", "Redoは確定変更を再適用し、Undoは未確定変更を戻したり古いVersionを作ったりします。"], ["ReplicationがあればBackupは不要です。", "誤削除や破損も複製されるため、別の時点へ戻せるBackupとRecovery訓練が必要です。"]],
      questions: [["Redo Logの目的は何ですか。","Crash後にCommit済みの変更を再適用して復元することです。","Redoは未Commit変更を取り消すためだけに使います。","RedoはReplicaへSQLを送る通信路そのものです。","「Crash後にCommit済みの変更を再適用して復元することです。」が正しいのは、Crash後にCommit済み変更を再適用しPageを復元するため。誤答1の「Redoは未Commit変更を取り消すためだけに使います。」はRedoとUndoの役割を逆にしている。誤答2の「RedoはReplicaへSQLを送る通信路そのものです。」は復旧Logと複製通信を同じものにしている。"],["Undoの目的は何ですか。","未Commitの変更を戻し、Rollbackや古いVersionの読み取りを支えることです。","UndoはCommit済み変更を再適用します。","Undoは別DBへ変更を複製する通信記録です。","「未Commitの変更を戻し、Rollbackや古いVersionの読み取りを支えることです。」が正しいのは、未Commit変更を戻しRollbackや古いVersionを支えるため。誤答1の「UndoはCommit済み変更を再適用します。」はRedoの再適用をUndoの仕事にしている。誤答2の「Undoは別DBへ変更を複製する通信記録です。」はReplicaへの配送と混同している。"],["WALの順序は何ですか。","データPageを確定させる前に、必要なLogを永続的に書きます。","Data Pageを先に書き後からLogを作ります。","WALはLogを保存せずMemoryだけで順序を記録します。","「データPageを確定させる前に、必要なLogを永続的に書きます。」が正しいのは、Data Pageより先に必要なLogを永続的に書くため。誤答1の「Data Pageを先に書き後からLogを作ります。」はWrite-Aheadの順番を逆にしている。誤答2の「WALはLogを保存せずMemoryだけで順序を記録します。」は永続記録を否定している。"],["Crash Recoveryで守る状態は何ですか。","Commit済みの変更は残し、未Commitの変更は取り消した状態です。","Crash後はCommit済みも未Commitも全て削除します。","Crash Recoveryは未Commit変更もそのまま公開します。","「Commit済みの変更は残し、未Commitの変更は取り消した状態です。」が正しいのは、Commit済みを残し未Commitを取り消す状態へ戻すため。誤答1の「Crash後はCommit済みも未Commitも全て削除します。」は復旧後の扱いを全削除にしている。誤答2の「Crash Recoveryは未Commit変更もそのまま公開します。」は未Commitを公開する説明になっている。"],["Replication Lagとは何ですか。","Sourceの変更がReplicaへ届き、適用されるまでの遅れです。","LagはSourceとReplicaの表名が違うことです。","LagはBackupの保存容量だけを示します。","「Sourceの変更がReplicaへ届き、適用されるまでの遅れです。」が正しいのは、Sourceの変更がReplicaへ届き適用されるまでの遅れだから。誤答1の「LagはSourceとReplicaの表名が違うことです。」は通信遅延を表名の違いとしている。誤答2の「LagはBackupの保存容量だけを示します。」は複製の時間を容量としている。"],["ReplicaだけでBackupを代用できない理由は何ですか。","誤削除や破損もReplicaへ複製される可能性があるからです。","Replicaは過去の任意時点を必ず保存します。","Replicaがあれば誤削除を自動で取り消します。","「誤削除や破損もReplicaへ複製される可能性があるからです。」が正しいのは、誤削除や破損も複製され、別時点へ戻せない可能性があるため。誤答1の「Replicaは過去の任意時点を必ず保存します。」はReplicaを時点Backupと同一視している。誤答2の「Replicaがあれば誤削除を自動で取り消します。」は削除の伝播を防ぐ機能としている。"],["直後の書き込みを必ず読ませたいとき、どこから読む選択がありますか。","遅延のないSource（Primary）から読む設計を検討します。","遅延するReplicaだけを選べば直後の値を必ず読めます。","読み取り先を選ばなくても全Replicaが同時更新されます。","「遅延のないSource（Primary）から読む設計を検討します。」が正しいのは、確定直後の値を持つSource（Primary）から読むため。誤答1の「遅延するReplicaだけを選べば直後の値を必ず読めます。」はReplica遅延を無視している。誤答2の「読み取り先を選ばなくても全Replicaが同時更新されます。」は複製が同時に完了するとしている。"]],
      checks: ["RedoとUndoの役割", "WALの書き込み順", "Crash Recovery", "ReplicationとLag", "Backupとの違い"], search: "Redo Log Undo WAL Write-Ahead Logging Crash Recovery InnoDB binlog replication source primary replica lag backup"
    })
  ];

  globalThis.registerPart("part-8", partChapters);
})();
